const lead = $('Loop Over Items').item.json;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const p = $json; // kết quả GET /api/properties/:id
const purposes = {
  REMINDER: 'Nhắc khách lịch xem nhà sẽ diễn ra trong 24 giờ tới. Nêu rõ giờ, tên căn, địa chỉ. Dặn khách báo lại nếu cần đổi giờ.',
  FEEDBACK: 'Khách đã đi xem nhà hôm trước. Cảm ơn, hỏi cảm nhận về căn nhà, gợi ý bước tiếp theo: xem thêm căn khác hoặc trao đổi về đặt cọc. Cuối email có nút "Gửi cảm nhận", hãy mời khách bấm nút đó và KHÔNG tự chèn đường link.',
  WARM_NUDGE: 'Khách WARM đã xem nhà cách đây vài ngày nhưng chưa phản hồi. Viết ĐÚNG 2 câu mở đầu ngắn gọn (dưới 250 ký tự), KHÔNG viết lời chào mở đầu (không "Chào anh/chị"), KHÔNG viết lời chào kết thúc, chỉ hỏi thăm nhẹ nhàng về căn nhà đã xem và hỏi thêm nhu cầu (khu vực, giá, số phòng).',
  HOT_NUDGE: '', COLD_NURTURE: '', EXPIRE_LEAD: '',
  STAFF_NUDGE: '',
  ATTENDANCE_CHECK: '',
  ATTENDANCE_ESCALATE: '',
};
const eventTypes = { HOT_NUDGE: 'HOT_NUDGE_SENT', COLD_NURTURE: 'COLD_NURTURE_STARTED', EXPIRE_LEAD: 'LEAD_EXPIRED_NOTIFIED', REMINDER: 'REMINDER_SENT', FEEDBACK: 'FEEDBACK_ASKED', WARM_NUDGE: 'WARM_NURTURE_STARTED', STAFF_NUDGE: 'RESPONSE_OVERDUE',
  ATTENDANCE_CHECK: 'ATTENDANCE_CHECK_SENT', ATTENDANCE_ESCALATE: 'ATTENDANCE_ESCALATED' };
return {
  json: {
    ...lead,
    nameHtml: esc(lead.name),
    needsHtml: esc(lead.needs),
    phoneHtml: esc(lead.phone),
    propertyName: p.name,
    propertyAddress: p.address,
    viewingTimeText: lead.type === 'STAFF_NUDGE' ? 'Chưa có lịch xem' : DateTime.fromISO(new Date(lead.viewing_time).toISOString()).setZone('Asia/Ho_Chi_Minh').toFormat("HH:mm 'ngày' dd/MM/yyyy"),
    purpose: purposes[lead.type],
    eventType: eventTypes[lead.type],
  },
};

