const rows = $input.all().map(i => i.json);
const failed = rows.filter(r => r.type === 'ERROR').length;
const skipped=rows.filter(r=>r.type==='SKIPPED').length;
const ok = rows.filter(r => !['ERROR','SKIPPED'].includes(r.type));
const count = t => ok.filter(r => r.type === t).length;
return [{
  json: {
    total: ok.length,
    skipped,
    failed,
    review: rows.filter(r=>r.needsReview).length,
    reminder: count('REMINDER'),
    feedback: count('FEEDBACK'),
    warmNudge: count('WARM_NUDGE'),
    staffNudge: count('STAFF_NUDGE'),
    hotNudge: count('HOT_NUDGE'),
    coldNurture: count('COLD_NURTURE'),
    expired: count('EXPIRE_LEAD'),
    attendanceCheck: count('ATTENDANCE_CHECK'),
    attendanceEscalate: count('ATTENDANCE_ESCALATE'),
    fallback: ok.filter(r => r.usedFallback).length,
  },
}];

const ctx=$('Chuẩn bị ngữ cảnh').item.json;
if(['STAFF_NUDGE','ATTENDANCE_CHECK','ATTENDANCE_ESCALATE','HOT_NUDGE','EXPIRE_LEAD'].includes(ctx.type)) return {json:$('Chuẩn bị thông báo NV').item.json};
if(ctx.type==='COLD_NURTURE') return {json:$('Chuẩn bị bản tin COLD').item.json};
return {json:$('Kiểm tra nội dung AI').item.json};

const email=$('Chuẩn bị ngữ cảnh').item.json.email.trim().toLowerCase();
if(!$json.contacts || typeof $json.contacts!=='object') throw new Error('Mautic không trả danh sách contact');
const matches=Object.values($json.contacts).filter(c=>String(c.fields?.all?.email??c.fields?.core?.email?.value??c.email??'').trim().toLowerCase()===email);
if(matches.length>1) throw new Error('Nhiều contact trùng email');
const id=matches.length?Number(matches[0].id):null;
if(matches.length&&(!Number.isSafeInteger(id)||id<=0))throw new Error('Contact ID không hợp lệ');
return {json:{contactId:id}};

const id=Number($json.contact?.id??$json.id);
if(!Number.isSafeInteger(id)||id<=0)throw new Error('Mautic không trả contact ID hợp lệ');
return {json:{contactId:id}};

const type=$('Loop Over Items').item.json.type;
if(type==='HOT_NUDGE' && $json.telegramSent!==true) throw new Error('Nhắc gọi HOT cần xác nhận Telegram thành công; kiểm tra cấu hình bot sale');
if(['STAFF_NUDGE','EXPIRE_LEAD'].includes(type) && $json.emailSent!==true) throw new Error('Chưa xác nhận gửi email quản lý cho lịch quá hạn');
if($json.emailSent!==true && $json.telegramSent!==true)throw new Error('Không kênh thông báo nào xác nhận thành công');
return {json:$json};
